394 static void complete_policy_scope_reset(void)
395 {
396 	const unsigned long pending = (1UL << 1) | (1UL << 2) | (1UL << 3)
397 				      | (1UL << 54);
398 
399 	/* Task mode must be zero before polling: a reschedule during a status
400 	 * syscall must not launch another selection-time mode-14 sweep. These
401 	 * CSR bits describe the prefix controller, not all UCE response slots.
402 	 */
403 	set_futex_early_mode(0);
404 	for (unsigned poll = 0; poll < COMPLETE_SCOPE_DRAIN_POLLS; ++poll)
405 		if (!(prefix_status() & pending))
406 			return;
407 	errno = ETIMEDOUT;
408 	fail("complete policy scope prefix-controller drain");
409 }
