425 static uint64_t retention_read_status(void)
426 {
427 	uint64_t status = 0;
428 
429 	if (retention_prctl(PR_BP_ICACHE_RETENTION_STATUS,
430 			    (unsigned long)&status, 0UL, 0UL, 0UL))
431 		fail("I-retention status/probe");
432 	if (!(status & (UINT64_C(1) << 63))) {
433 		errno = ENODEV;
434 		fail("I-retention capability absent");
435 	}
436 	return status;
437 }
