439 static void retention_cleanup(void)
440 {
441 	int status;
442 	pid_t waited;
443 
444 	/* The policy is CPU-global. Inherited child exit handlers must never
445 	 * disable it during the parent's measurement or another child's work.
446 	 */
447 	if (getpid() != retention_owner)
448 		return;
449 	if (retention_child > 0) {
450 		do { waited = waitpid(retention_child, &status, WNOHANG); }
451 		while (waited < 0 && errno == EINTR);
452 		if (!waited) {
453 			kill(retention_child, SIGKILL);
454 			while (waitpid(retention_child, &status, 0) < 0 && errno == EINTR) { }
455 		}
456 		retention_child = 0;
457 	}
458 	if (retention_armed) {
459 		if (retention_prctl(PR_BP_ICACHE_RETENTION_CONTROL, 0UL, 0UL, 0UL, 0UL)) {
460 			perror("I-retention error cleanup/reset");
461 			_Exit(1);
462 		}
463 		retention_armed = 0;
464 	}
465 }
