467 static void retention_initialize(void)
468 {
469 	retention_owner = getpid();
470 	if (atexit(retention_cleanup))
471 		fail("I-retention cleanup registration");
472 	(void)retention_read_status();
473 	retention_armed = 1;
474 	/* Exec need not clear an old per-task preview mode. Retention tests
475 	 * must not accidentally inherit kernel wake hints from earlier code.
476 	 * Explicit futex policies rearm their own mode later as before.
477 	 */
478 	set_futex_early_mode(0);
479 }
