481 static unsigned retention_mode(enum hint_policy policy, unsigned enabled)
482 {
483 	if (!enabled)
484 		return 0;
485 	return policy == hint_retention_rr ? 1 : policy == hint_retention_first ? 2 : 0;
486 }
