488 static void retention_start_cell(enum hint_policy policy, unsigned enabled)
489 {
490 	unsigned mode = retention_mode(policy, enabled);
491 
492 	retention_armed = 1;
493 	/* Both processes have allocated private state and completed setup fences.
494 	 * One global write/fence resets this cell; no per-wake hint is emitted.
495 	 */
496 	if (retention_prctl(PR_BP_ICACHE_RETENTION_CONTROL, (unsigned long)mode,
497 			    0UL, 0UL, 0UL))
498 		fail("I-retention policy control");
499 	if ((retention_read_status() & 3) != mode) {
500 		errno = EIO;
501 		fail("I-retention policy readback");
502 	}
503 }
504 
505 static uint64_t retention_finish_cell(enum hint_policy policy, unsigned enabled)
506 {
507 	uint64_t status = retention_read_status();
508 
509 	if ((status & 3) != retention_mode(policy, enabled)) {
510 		errno = EIO;
511 		fail("I-retention policy changed during cell");
512 	}
513 	if (retention_prctl(PR_BP_ICACHE_RETENTION_CONTROL, 0UL, 0UL, 0UL, 0UL))
514 		fail("I-retention normal reset");
515 	if (retention_read_status() & 3) {
516 		errno = EIO;
517 		fail("I-retention reset readback");
518 	}
519 	retention_armed = 0;
520 	return status;
521 }
